INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4641234', 'The Buganda Agreement, 1955', 'The Buganda Agreement (1955) was made on 18 October 1955 between Andrew Cohen, the governor of the Uganda Protectorate, and Mutesa II, Kabaka of Buganda. The agreement facilitated Mutesa II''s return as a constitutional monarch of Buganda, ending the Kabaka crisis that began when the Kabaka was exiled to England by Cohen in 1953.', 1955, 10, 18, NULL, NULL, NULL, 'day', '18 October 1955', 30, 'https://en.wikipedia.org/wiki/Buganda_Agreement_(1955)'),
  ('Q3653895', '1971 Ugandan coup d''état', 'A military coup d''état overthrew the president of Uganda, Milton Obote, on 25 January 1971. It took place while Obote was attending the Commonwealth Heads of Government Meeting in Singapore, and was staged by Idi Amin, the commander of the Uganda Army at the time.', 1971, 1, 25, NULL, NULL, NULL, 'day', '25 January 1971', 48, 'https://en.wikipedia.org/wiki/1971_Ugandan_coup_d''%C3%A9tat'),
  ('Q202465', 'Uganda–Tanzania War', 'The Uganda–Tanzania War, known in Tanzania as the Kagera War (Swahili: Vita vya Kagera) and in Uganda as the 1979 Liberation War, was fought between Uganda and Tanzania from October 1978 until June 1979 and led to the overthrow of Ugandan President Idi Amin. The war was preceded by a deterioration of relations between Uganda and Tanzania following Amin''s 1971 overthrow of President Milton Obote, who was close to the President of Tanzania, Julius Nyerere.', 1979, 6, 3, 1979, 6, 3, 'day', '3 June 1979', 69, 'https://en.wikipedia.org/wiki/Uganda%E2%80%93Tanzania_War'),
  ('Q5432160', 'Fall of Kampala', 'The Fall of Kampala, also known as the Liberation of Kampala (Swahili: Kukombolewa kwa Kampala), was a battle during the Uganda–Tanzania War in 1979, in which the combined forces of Tanzania and the Uganda National Liberation Front (UNLF) attacked and captured the Ugandan capital, Kampala. As a result, Ugandan President Idi Amin was deposed, his forces were scattered, and a UNLF government was installed.', 1979, 4, 11, NULL, NULL, NULL, 'day', '11 April 1979', 37, 'https://en.wikipedia.org/wiki/Fall_of_Kampala'),
  ('Q3119017', 'Ugandan Bush War', 'The Ugandan Bush War was a civil war fought in Uganda by the official Ugandan government and its armed wing, the Uganda National Liberation Army (UNLA), against a number of rebel groups, most importantly the National Resistance Army (NRA), from 1980 to 1986. The unpopular President Milton Obote was overthrown in a coup d''état in 1971 by General Idi Amin, who established a military dictatorship.', 1980, 10, 6, 1986, 1, 25, 'day', '6 October 1980 – 25 January 1986', 55, 'https://en.wikipedia.org/wiki/Ugandan_Bush_War'),
  ('Q842380', 'Second Sudanese Civil War', 'The Second Sudanese Civil War was a conflict from 1983 to 2005 between the central Sudanese government and the Sudan People''s Liberation Army. It was largely a continuation of the First Sudanese Civil War of 1955 to 1972.', 1983, 6, 5, 2005, 1, 9, 'day', '5 June 1983 – 9 January 2005', 69, 'https://en.wikipedia.org/wiki/Second_Sudanese_Civil_War'),
  ('Q126318653', '1985 Ugandan coup d''état', 'The 1985 Ugandan coup d''état was an ethnically motivated military takeover in Uganda involving dissident Acholi elements within the Uganda National Liberation Army (UNLA), led by Brigadier Basilio Olara Okello, which successfully ousted the second Milton Obote government. The army promptly named General Tito Okello Lutwa as President of the Military Council, only for him to be ousted six months later by Yoweri Museveni and his National Resistance Army (NRA).', 1985, 7, 27, NULL, NULL, NULL, 'day', '27 July 1985', 26, 'https://en.wikipedia.org/wiki/1985_Ugandan_coup_d''%C3%A9tat'),
  ('Q105587935', 'War in Uganda (1986–1994)', 'From 1986 to 1994, a variety of rebel groups waged a civil war against the Ugandan government of President Yoweri Museveni. Most of the fighting took place in the country''s north and east, although the western and central regions were also affected.', 1986, 3, NULL, 1994, 2, NULL, 'month', 'March 1986 – February 1994', 39, 'https://en.wikipedia.org/wiki/War_in_Uganda_(1986%E2%80%931994)'),
  ('Q303801', 'Lord''s Resistance Army insurgency', 'The Lord''s Resistance Army insurgency is an ongoing conflict between the Lord''s Resistance Army (LRA), a Ugandan militant religious extremist group, against the government of Uganda. Following the Ugandan Civil War, militant Joseph Kony formed the Lord''s Resistance Army and launched an insurgency against the newly installed President Yoweri Museveni.', 1987, NULL, NULL, NULL, NULL, NULL, 'year', '1987', 52, 'https://en.wikipedia.org/wiki/Lord''s_Resistance_Army_insurgency'),
  ('Q838695', 'First Congo War', 'The First Congo War, also known as Africa''s First World War, was a civil and international military conflict that lasted from 24 October 1996 to 16 May 1997, primarily taking place in Zaire (which was renamed the Democratic Republic of the Congo during the conflict). The war resulted in the overthrow of Zairean President Mobutu Sese Seko, who was replaced by rebel leader Laurent-Désiré Kabila.', 1996, 10, 24, 1997, 5, 16, 'day', '24 October 1996 – 16 May 1997', 72, 'https://en.wikipedia.org/wiki/First_Congo_War'),
  ('Q16960307', 'Allied Democratic Forces insurgency', 'The Allied Democratic Forces insurgency is an ongoing conflict waged by the Islamic State-aligned Allied Democratic Forces (ADF) in Uganda and the Democratic Republic of the Congo (DRC), against the governments of those two countries and the MONUSCO. The insurgency began in 1996, intensifying in 2013, resulting in hundreds of deaths. The ADF is known to currently control a number of hidden camps which are home to about 2,000 people; in these camps, the ADF operates as a proto-state with "an internal security service, a prison, health clinics, and an orphanage" as well as schools for boys…', 1996, NULL, NULL, NULL, NULL, NULL, 'year', '1996', 43, 'https://en.wikipedia.org/wiki/Allied_Democratic_Forces_insurgency'),
  ('Q75756', 'Second Congo War', 'The Second Congo War, also known as Africa''s World War or the Great War of Africa, was a major conflict that began on 2 August 1998 in the Democratic Republic of the Congo (DRC), just over a year after the First Congo War. The war initially erupted when Congolese president Laurent-Désiré Kabila turned against his former allies from Rwanda and Uganda, who had helped him seize power.', 1998, 8, 2, 2003, 6, 30, 'day', '2 August 1998 – 30 June 2003', 75, 'https://en.wikipedia.org/wiki/Second_Congo_War'),
  ('Q139236054', 'Ngogo chimpanzee war', 'The Western and Central factions of chimpanzees of the Ngogo hill region in Kibale National Park, Uganda, have been engaged in a violent conflict since 2015. The conflict has been characterized by one-sided violence, including killing, brutal attacks, and mutilations, by the Western faction against the Central faction.', 2015, NULL, NULL, NULL, NULL, NULL, 'year', '2015', 50, 'https://en.wikipedia.org/wiki/Ngogo_Chimpanzee_War'),
  ('Q55887234', '2018–2020 Kivu Ebola epidemic', 'The Kivu Ebola epidemic was an outbreak of Ebola virus disease (EVD) mainly in eastern Democratic Republic of the Congo (DRC), and in other parts of Central Africa, from 2018 to 2020. Between 1 August 2018 and 25 June 2020 it resulted in 3,470 reported cases.', 2018, 8, 1, NULL, NULL, NULL, 'day', '1 August 2018', 58, 'https://en.wikipedia.org/wiki/Kivu_Ebola_epidemic'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods'),
  ('Q119616154', 'Mpondwe school massacre', 'On 16 June 2023 rebels of the Allied Democratic Forces (ADF), a jihadist group linked to the Islamic State, attacked a secondary school in Mpondwe, a town in western Uganda''s Kasese District on the border with the Democratic Republic of the Congo. 42 people were killed, including 38 students; 8 were injured.', 2023, 6, 16, NULL, NULL, NULL, 'day', '16 June 2023', 45, 'https://en.wikipedia.org/wiki/Mpondwe_school_massacre');
